import {labContext,publishScan,connectLab} from '../labBridge.js';
import {SCENARIOS,DEFAULT_SETTINGS,FREQUENCIES,VERSION,newRecord,outcome,takeMeasurement,engineeringResult,makeWaveform,frequencySeries,validateSettings,exportRecord,updatePoleDetails,updateMeasurementGeometry} from './domain.js';
import {captureView,measurementCards,poleSummaryView} from './capture-ui.js';
import {installPhotos} from './photos.js';
const openPhonePreview=()=>window.focus();
import {googleMapUrls,monitorSurveyMap} from './survey-location.js';
import {beginAcquisition,finishAcquisition,completeScanDetails,SCAN_DURATION_MS} from './acquisition.js';

const paths={wave:'M2 12h4l3-8 5 16 4-11 3 3h2',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z M8 12l3 3 5-6',chart:'M4 3v17h17 M8 15l4-6 4 4 5-8',pole:'M11 22V2h2v20 M4 6h16 M7 6v4 M17 6v4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',probe:'M8 4h8v15H8z M10 1v3 M14 1v3 M10 19v3 M14 19v3 M10 8h4',arrow:'M5 12h14 M14 7l5 5-5 5',external:'M14 3h7v7 M21 3 10 14 M10 5H4v15h15v-6',check:'M5 12l4 4L19 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v.1',alert:'m12 3 10 18H2L12 3Z M12 9v5 M12 17v.1',repeat:'M3 10a9 9 0 0 1 16-5l2 2 M21 2v5h-5 M21 14a9 9 0 0 1-16 5l-2-2 M3 22v-5h5',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',plus:'M12 4v16 M4 12h16',flask:'M9 2h6 M10 2v7L4 19q-1 3 3 3h10q4 0 3-3L14 9V2 M7 15h10',layers:'m12 3 10 5-10 5L2 8l10-5Z M2 12l10 5 10-5 M2 16l10 5 10-5',battery:'M2 7h17v10H2z M22 10v4 M5 10h8v4H5z',link:'m9 15 6-6 M7 14l-2 2a4 4 0 0 0 6 6l3-3 M10 5l3-3a4 4 0 0 1 6 6l-2 2',close:'m6 6 12 12 M18 6 6 18',menu:'M4 6h16 M4 12h16 M4 18h16',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h8'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.wave}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='pole-lab-axonic-p23';
let sizeMode='circumference',draft=null,scanSession=null;
let storageOK=true,records={},scenario='normal',busy=false,toastTimer,selectedMeasurement='',signalMode='normalised',showReference=true,researchEnabled=false,operatorAdd=false,pendingPosition={height:0,direction:0,circumference:940};
try{const saved=JSON.parse(sessionStorage.getItem(KEY)||'null'); if(saved&&saved.version===VERSION){records=saved.records||{};scenario=SCENARIOS[saved.scenario]?saved.scenario:'normal';researchEnabled=!!saved.researchEnabled;}}catch{storageOK=false;}
for(const [key,record] of Object.entries(records)){if(!SCENARIOS[key]||!record?.asset||!Array.isArray(record.measurements)||!Array.isArray(record.history)||!record.settings||!Array.isArray(record.research)||!Array.isArray(record.calibrationEvents))delete records[key];}
let record=records[scenario]||newRecord(scenario);records[scenario]=record;
function positionFromRecord(){const m=record.measurements.at(-1);return {height:m?.height??0,direction:m?.direction??0,circumference:m?.circumference??record.asset.circumference};}
pendingPosition=positionFromRecord();
if(labContext){
 record=newRecord('normal');records={normal:record};scenario='normal';
 Object.assign(record.asset,{id:labContext.id,species:labContext.species,length:labContext.length,height:labContext.height,circumference:labContext.circumference});
 pendingPosition={height:labContext.scanHeight,direction:0,circumference:labContext.circumference};
 draft={poleId:record.asset.id,species:record.asset.species,length:record.asset.length,poleHeight:record.asset.height,scanHeight:pendingPosition.height,size:Math.round(pendingPosition.circumference),canonicalSize:pendingPosition.circumference};
}

const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const allowedRoutes=['field','field/result','asset','axonic/map','axonic/records','axonic/recent','analyser/summary','analyser/location','analyser/detail','analyser/measurements','analyser/signal','analyser/history','research','probes','settings'];
const route=()=>allowedRoutes.includes(location.hash.slice(1))?location.hash.slice(1):'asset';
const isAnalyser=()=>route().startsWith('analyser')||route()==='research';
const btn=(label,action,kind='',ic='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${busy?'disabled':''}>${ic?icon(ic):''}${label}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${text}</span>`;
const time=t=>new Intl.DateTimeFormat('en-NZ',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t));
const heightLabel=m=>m.height===0?'Groundline':`${m.height>0?'+':''}${m.height} mm AGL`;
const measureLabel=m=>`${m.id} · ${heightLabel(m)} · ${m.direction===0?'A':'B'}`;
const loadValue=(v,digits=1)=>record.settings.units==='imperial'?`${Math.round(v*224.808943).toLocaleString('en-NZ')} lbf`:`${v.toFixed(digits)} kN`;
function save(){records[scenario]=record;try{sessionStorage.setItem(KEY,JSON.stringify({version:VERSION,scenario,records,researchEnabled}));storageOK=true;}catch{storageOK=false;}}
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),3600);}
function go(to){if(location.hash.slice(1)===to)render();else location.hash=to;}
function navLink(to,label,ic,active){return `<a class="navlink ${active?'active':''}" href="#${to}" ${active?'aria-current="page"':''} title="${label}">${icon(ic)}<span>${label}</span></a>`;}
function render(){
  publishScan(busy);
  const r=route(),field=r.startsWith('field'),host=r==='asset'||r.startsWith('axonic/'),map=r==='analyser/location'||r==='axonic/map';
  const title=host?'Axonic':field?'Safe2Climb':r==='probes'?'Probes':r==='settings'?'Settings':r==='research'?'Expert / Research':'UB1000 Analyser';
  document.title=title+' · Axonic mockup';
  app.innerHTML='<div class="workspace axonic-native '+(host?'host-shell ':'')+(map?'map-workspace':'')+'"><header class="native-topbar">'+(host?'':'<a href="#asset" class="native-back" aria-label="Back to Axonic Capture">‹</a>')+'<div class="native-title"><h1>'+title+'</h1></div><button type="button" class="native-menu" data-action="mobile-menu" aria-label="Open tools" '+(busy&&!host?'disabled':'')+'>'+icon('menu')+'</button></header>'+(!host?'<nav class="native-tabs" aria-label="Workflow"><a href="#analyser/summary" '+(r!=='analyser/location'?'aria-current="page"':'')+'>Data</a><a href="#analyser/location" '+(r==='analyser/location'?'aria-current="page"':'')+'>Location</a></nav>':'<nav class="native-tabs host-tabs" aria-label="Axonic">'+[['asset','Capture'],['axonic/map','Map'],['axonic/records','Records'],['axonic/recent','Recent']].map(([to,label])=>'<a href="#'+to+'" '+(r===to?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav>')+'<main id="main" class="'+(map?'map-main':r==='field'||r==='analyser/summary'?'capture-main':'detail-main')+'" tabindex="-1">'+renderPage(r)+'</main><footer class="native-footer">Prototype · no live Axonic connection · no climb authorisation</footer></div>';
  monitorSurveyMap(app);
}
function locationPage(){const urls=googleMapUrls(record);return '<section class="survey-location" aria-label="Survey location"><div class="map-frame"><iframe class="survey-map" title="Survey location on Google Maps" src="'+urls.embed+'" loading="eager" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a class="map-unavailable map-open-icon" hidden href="'+urls.open+'" target="_blank" rel="noreferrer" aria-label="Map unavailable in this preview; open survey location in Google Maps" title="Open in Google Maps">'+icon('external')+'</a></div></section>';}
function heading(eyebrow,title,description='',actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function renderPage(r){
  if(r==='field')return fieldPage();
  if(r==='field/result')return `${heading('Pre-climb inspection','Safe2Climb result')}${['ready','repeat','additional'].includes(outcome(record))?'<p>No completed assessment yet.</p><a class="btn primary" href="#field">Return to capture</a>':resultCard(outcome(record))}`;
  if(r==='analyser/summary')return operatorAnalyserPage();
  if(r==='analyser/location')return locationPage();
  if(r.startsWith('analyser/'))return analyserPage(r.split('/')[1]);
  if(r==='asset')return assetPage();
  if(r==='axonic/map')return locationPage();
  if(r==='axonic/records'||r==='axonic/recent')return hostRecordsPage(r==='axonic/recent');
  if(r==='probes')return probePage();
  if(r==='settings')return settingsPage();
  if(r==='research')return researchPage();
}
function assetStrip(){return `<div class="asset-strip"><div class="asset-icon">${icon('pole')}</div><div><h2>Pole ${esc(record.asset.id)}</h2><p>${esc(record.asset.species)} · ${record.asset.length} m · ${record.asset.circumference} mm at GL</p></div><button class="btn-link" data-action="pole-context" aria-label="Review pole details">Details ${icon('arrow')}</button></div>`;}
function contextPanel(){return `<aside class="stack context-panel"><section class="panel"><div class="panel-body"><h3>Pole context</h3><dl class="keyvals"><div><dt>Asset record</dt><dd>${esc(record.asset.id)}</dd></div><div><dt>Work package</dt><dd>Demonstration</dd></div><div><dt>Above ground</dt><dd>${record.asset.height} m</dd></div><div><dt>GL circumference</dt><dd>${record.asset.circumference} mm</dd></div><div><dt>Recorded lean</dt><dd>${record.asset.lean}°</dd></div></dl><div class="divider"></div><p class="context-note">${icon('link')}Carried through from the Axonic demo record.</p><a class="btn-link" href="#asset">View pole information ${icon('arrow')}</a></div></section><section class="panel"><div class="panel-body"><h3>One shared assessment</h3><p class="context-note">Readings, probe details, and results stay with this pole when you open the Analyser.</p><div class="divider"></div><p class="context-note">Existing pre-climb checks remain in Axonic. This ultrasonic screen complements that process.</p></div></section></aside>`;}
function placement(additional=false,position=null){
  const p=position||{height:additional?300:0,direction:additional?90:0};
  const label=heightLabel(p),direction=p.direction===0?'A':'B';
  const y=p.height>0?80:p.height<0?150:120;
  return `<div class="placement"><svg role="img" aria-label="Two opposite probes at ${esc(label)}, direction ${direction}; schematic, not to scale" viewBox="0 0 470 190"><path d="M113 20 106 177H154L148 20" fill="#24232c" stroke="#57515f"/><path d="M50 136H205" stroke="#888073" stroke-dasharray="4 4"/><text x="54" y="126" class="placement-label">GL</text><rect x="90" y="${y}" width="22" height="14" rx="4" fill="#bb9bff"/><rect x="150" y="${y}" width="22" height="14" rx="4" fill="#bb9bff"/>${p.height!==0?'<text x="180" y="'+(y+10)+'" class="placement-value">'+p.height+' mm</text>':''}<circle cx="345" cy="92" r="49" fill="#201d28" stroke="#6b6079"/><circle cx="345" cy="92" r="32" fill="none" stroke="#39333f" stroke-dasharray="3 5"/><g transform="rotate(${p.direction} 345 92)"><path d="M296 92H394" stroke="#bb9bff" stroke-dasharray="4 4"/><rect x="286" y="84" width="20" height="16" rx="4" fill="#bb9bff"/><rect x="384" y="84" width="20" height="16" rx="4" fill="#bb9bff"/></g><text x="345" y="166" text-anchor="middle" class="placement-value">Direction ${direction}</text><text x="345" y="20" text-anchor="middle" class="placement-label">TOP VIEW</text></svg></div>`;
}
function fieldPage(){return captureView({record,position:pendingPosition,busy,field:true,state:outcome(record),result:engineeringResult(record),loadValue,sizeMode,storageOK,draft,session:scanSession});}
function acquisitionCard(state){
  const additional=state==='additional',repeat=state==='repeat',ready=record.connected&&record.calibration==='current-demo';
  const title=additional?'One more reading needed':repeat?'Check contact and repeat':'Place probes at groundline';
  const description=additional?'The first reading is inconclusive. Move to the illustrated plane and use the other direction.':repeat?'The signal was too poor to assess. Check that both probes are firmly seated, then repeat at the same position.':'Use the marked groundline position. Keep both probes still until the capture is complete.';
  return `<section class="panel capture"><div class="capture-header"><span class="step">${additional?'ADDITIONAL READING':repeat?'REPEAT / SAME POSITION':'GROUNDLINE'}</span>${badge(additional?'Inconclusive':repeat?'Reading rejected':ready?'Ready':'Probe attention',additional||repeat||!ready?'yellow':'')}</div><div class="capture-content"><h2>${title}</h2><p>${description}</p>${placement(additional,repeat?record.measurements.at(-1):null)}<div class="probe-readiness">${icon('probe')}<span>${record.connected?'Both probes connected':'Probes disconnected'}</span><span>${record.connected?'81% / 51%':''}</span></div>${ready?btn(additional?'Take additional reading':repeat?'Repeat reading':'Take reading','capture','primary field','wave'):'<a class="btn primary field" href="#probes">Check probes '+icon('arrow')+'</a>'}<div class="capture-foot">${additional?'Demo placement · +300 mm above GL · direction B':'Quality checked and saved automatically'}</div></div>${additional||repeat?`<div class="hint-row">${icon(additional?'layers':'repeat')}<span>${additional?'The original reading stays in this assessment.':'The rejected attempt stays in history. No strength estimate was produced.'}</span></div>`:''}</section>`;
}
function operatorAnalyserPage(){return captureView({record,position:pendingPosition,busy,field:false,state:outcome(record),result:engineeringResult(record),loadValue,sizeMode,storageOK,draft,session:scanSession});}
function positionRow(){return `<div class="position-row"><div><span>Measurement position</span><strong>${pendingPosition.height===0?'Groundline':`${pendingPosition.height>0?'+':''}${pendingPosition.height} mm AGL`} · direction ${pendingPosition.direction===0?'A':'B'}</strong></div><button class="btn-link" data-action="position">Change</button></div>`;}
function resultCard(state){
  const clear=state==='clear',restricted=state==='restricted',last=record.measurements.at(-1),usable=last?.quality==='accepted';
  return `<section class="panel"><div class="result-content" aria-live="polite"><div class="status-icon ${clear?'':restricted?'red':'yellow'}">${icon(clear?'check':'alert')}</div><div class="eyebrow">${restricted?'Existing asset restriction':'Demo assessment result'}</div><h2>${clear?'No deterioration indication':restricted?'Refer to the asset restriction':'Engineering review required'}</h2><p>${clear?'The demo reading is usable and shows no deterioration indication. Continue the established pre-climb assessment.':restricted?esc(record.asset.restriction):record.concern?'A pre-climb concern has been recorded. Follow the existing review process before proceeding.':scenario==='inconclusive'?'The additional reading has not resolved the uncertainty. Keep both readings and refer the assessment for engineering review.':'A deterioration indication needs a closer assessment. Review the pole and its loading before deciding on the next action.'}</p><div class="result-meta"><div><small>Measurement quality</small>${restricted||!last?'Not assessed':usable?'Usable':'Rejected'}</div><div><small>Readings retained</small>${record.measurements.length}</div><div><small>Record</small>${storageOK?'Saved on this device':'Session only'}</div></div><div class="result-actions">${clear?'<a class="btn primary" href="#asset">Return to pole '+icon('arrow')+'</a>':'<a class="btn primary" href="#analyser/summary">Open detailed assessment '+icon('arrow')+'</a>'}${clear?'<a class="btn ghost" href="#analyser/summary">View analysis</a>':btn(record.reviewRequested?'Review recorded':'Record review request','request-review','ghost')}</div><p class="subtle-note">${clear?'This result does not authorise climbing.':'Follow the existing asset-owner process. This prototype sends no notifications.'}</p></div><div class="hint-row">${icon('file')}<span>${restricted?'Axonic restriction takes precedence in this demonstration.':!last?'Concern recorded. No ultrasonic reading has been taken.':'Capture complete. The full record is available in History.'}</span></div></section>`;
}
function analyserPage(tab){return `${heading('Optional engineering detail','Assessment detail',`Pole ${esc(record.asset.id)}`,`<a class="btn ghost" href="#analyser/summary">Back to collection</a>`)}<div class="tabs" role="tablist" aria-label="Analysis views">${[['detail','Overview'],['measurements','Measurements'],['signal','Signal & model'],['history','History']].map(([key,label])=>`<button class="tab" role="tab" aria-selected="${tab===key}" data-route="analyser/${key}">${label}</button>`).join('')}</div><div role="tabpanel">${tab==='detail'?summaryPage():tab==='measurements'?measurementsPage():tab==='signal'?signalPage():historyPage()}</div>`;}
function summaryPage(){
  const result=engineeringResult(record);
  if(!result)return `<section class="panel empty">${icon(outcome(record)==='repeat'?'repeat':'wave')}<h2>${outcome(record)==='additional'?'More evidence is needed':outcome(record)==='repeat'?'No estimate from this reading':'No engineering estimate yet'}</h2><p>${outcome(record)==='repeat'?'The last capture failed its quality check. A numeric strength result is withheld.':outcome(record)==='additional'?'The groundline result is inconclusive. Take the requested additional reading before reviewing an illustrative capacity.':'Capture a usable reading to review this scenario’s illustrative strength and capacity.'}</p><a class="btn primary" href="#field">${outcome(record)==='ready'?'Take first reading':'Continue guided assessment'} ${icon('arrow')}</a></section>${measurementTable()}`;
  const max=14,unit=record.settings.units==='imperial'?'lbf':'kN',val=record.settings.units==='imperial'?Math.round(result.capacity*224.808943).toLocaleString('en-NZ'):result.capacity.toFixed(1);
  return `<div class="summary-top"><section class="panel capacity-panel"><div class="toolbar"><p class="engineering-label">Estimated residual tip capacity</p>${badge('Demo values','yellow')}</div><div class="big-number">${val} <small>${unit}</small></div><p class="range">Illustrative range <b>${loadValue(result.range[0])} – ${loadValue(result.range[1])}</b></p><div class="capacity-scale"><span class="interval" style="left:${result.range[0]/max*100}%;width:${(result.range[1]-result.range[0])/max*100}%"></span><span class="point" style="left:${result.capacity/max*100}%"></span></div><div class="scale-labels"><span>0 ${unit}</span><span>${loadValue(max)}</span></div><p class="subtle-note">Uncertainty display concept · statistical coverage not established</p></section><div class="stat-grid"><section class="panel stat"><h3>Relative to reference</h3><div class="value">${result.percent}<small>%</small></div><p>Reference: ${loadValue(result.reference)} · demo</p></section><section class="panel stat"><h3>Local fibre strength</h3><div class="value">${result.fibre.toFixed(1)} <small>MPa</small></div><p>${result.fibreRange[0]}–${result.fibreRange[1]} MPa · demo range</p></section><section class="panel stat"><h3>Measurement quality</h3><div class="value">Usable</div><p>${record.measurements.filter(m=>m.quality==='accepted').length} accepted · ${record.measurements.filter(m=>m.quality==='rejected').length} rejected</p></section><section class="panel stat"><h3>Governing section</h3><div class="value">${result.governing}</div><p>Illustrative selection · see measurements</p></section></div></div><div class="assessment-note">${icon('info')}<div><h3>${outcome(record)==='clear'?'No deterioration indication in this demo':'Engineering review required'}</h3><p>${outcome(record)==='clear'?'This result complements the existing inspection and loading assessment.':'Consider the indicated section, other defects, and the intended loading. A local fibre-strength estimate alone does not establish whole-pole adequacy.'} All numbers are scenario fixtures. No validated engineering model or climb threshold is implemented.</p></div></div>${measurementTable()}<div class="section-heading"><h2>Understand the result</h2></div><div class="two-col"><a class="panel action-tile" href="#analyser/signal">${icon('wave')}<div><h3>Signal & model</h3><p>Trace the measurement, processing concept, and assumptions.</p></div>${icon('arrow')}</a><a class="panel action-tile" href="#analyser/history">${icon('clock')}<div><h3>Assessment history</h3><p>Every capture, rejected attempt, and review request.</p></div>${icon('arrow')}</a></div>`;
}
function measurementTable(){if(!record.measurements.length)return '';return `<div class="section-heading"><h2>Measurement record</h2><a class="btn-link" href="#analyser/measurements">View all ${icon('arrow')}</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Reading</th><th>Position</th><th>Direction</th><th>Quality</th><th>Signal</th></tr></thead><tbody>${record.measurements.map(m=>`<tr><td>${m.id}</td><td>${heightLabel(m)}</td><td>${m.direction===0?'A · 0°':'B · 90°'}</td><td>${badge(m.quality==='accepted'?'Usable':'Rejected',m.quality==='accepted'?'':'yellow')}</td><td><button class="table-btn" data-measurement="${m.id}">Inspect ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function measurementsPage(){
  if(!record.measurements.length)return `<div class="panel empty"><h2>No readings captured</h2><p>The same acquisition service is used by both workflows.</p>${btn('Add measurement','add','primary','plus')}</div>`;
  return `<div class="toolbar"><p class="research-note">Every attempt is retained. Geometry belongs to each measurement plane.</p>${btn('Export demo record','export','ghost','download')}</div>${measurementTable()}<details class="model-section"><summary>Acquisition details</summary><div class="inline-content"><div class="table-wrap"><table class="data-table"><thead><tr><th>Reading</th><th>Circumference</th><th>Pair</th><th>Voltage / gain</th><th>Tx count</th><th>Calibration</th><th>Captured</th></tr></thead><tbody>${record.measurements.map(m=>`<tr><td>${m.id}</td><td>${m.circumference} mm</td><td>${esc(m.settings.group)}</td><td>${m.settings.voltage} V / ${m.settings.gain}</td><td>${m.settings.txCount}</td><td>${esc(m.calibrationId)}</td><td>${time(m.time)}</td></tr>`).join('')}</tbody></table></div><p class="subtle-note">Capture metadata is frozen with each reading. Changing settings later does not rewrite earlier measurements.</p></div></details><div class="assessment-note">${icon('layers')}<div><h3>One record across both workflows</h3><p>Rejected readings are excluded from result fixtures, never converted to zero or silently removed. Additional readings retain height, circumference, and direction. No automatic averaging or weakest-section algorithm has been validated in this prototype.</p></div></div>`;
}
function getSelectedMeasurement(){return record.measurements.find(m=>m.id===selectedMeasurement)||record.measurements.at(-1);}
function waveformChart(m){
  const normalised=signalMode!=='raw';const samples=makeWaveform(m,normalised,m.settings.frequency);const raw=makeWaveform(m,false,m.settings.frequency);
  const points=data=>data.map((p,i)=>`${i?'L':'M'}${(50+p.x/1000*670).toFixed(1)},${(132-p.y*83).toFixed(1)}`).join(' ');
  const reference=Array.from({length:200},(_,i)=>{const t=i*5;return {x:t,y:Math.exp(-(((t-340)/105)**2))*.85+Math.exp(-(((t-585)/130)**2))*.52};});
  return `<svg class="chart" role="img" aria-label="Synthetic ${signalMode} waveform for ${m.id}, with time in microseconds and arbitrary amplitude units" viewBox="0 0 760 275"><text x="50" y="15">Amplitude · a.u. · synthetic</text>${[49,90,132,173,214].map(y=>`<path class="grid" d="M50 ${y}H720"/>`).join('')}${[0,200,400,600,800,1000].map(x=>`<path class="grid" d="M${50+x/1000*670} 30V224"/><text x="${50+x/1000*670}" y="245" text-anchor="middle">${x}</text>`).join('')}<text x="27" y="53">1</text><text x="27" y="136">0</text><text x="22" y="218">−1</text><text x="390" y="268" text-anchor="middle">Time (µs)</text>${showReference?`<path class="trace secondary" d="${points(reference)}"/>`:''}${signalMode==='overlay'?`<path fill="none" stroke="#70798b" stroke-width="1.5" d="${points(raw)}"/>`:''}<path class="trace" d="${points(samples)}"/></svg>`;
}
function signalPage(){
  const m=getSelectedMeasurement();
  if(!m)return `<section class="panel empty"><h2>No waveform yet</h2><p>Capture a reading to inspect its signal and processing metadata.</p><a class="btn primary" href="#field">Open guided capture</a></section>`;
  return `<div class="toolbar"><div class="field"><label for="signal-reading">Measurement</label><select class="control" id="signal-reading">${record.measurements.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${measureLabel(x)}${x.quality==='rejected'?' · rejected':''}</option>`).join('')}</select></div><div class="segmented" aria-label="Signal view">${[['raw','Raw'],['normalised','Normalised'],['overlay','Overlay']].map(([key,label])=>`<button class="${key===signalMode?'active':''}" aria-pressed="${key===signalMode}" data-signal-mode="${key}">${label}</button>`).join('')}</div></div>${m.quality==='rejected'?'<div class="notice">This capture was rejected. Missing arrivals and energy metrics remain unavailable.</div>':''}<section class="panel chart-panel"><div class="toolbar"><h2>Signal comparison</h2>${badge('Synthetic waveform','yellow')}</div><div class="chart-controls"><label><input id="show-reference" type="checkbox" ${showReference?'checked':''}> Show illustrative reference envelope</label><span class="small muted">Analysis band ${m.settings.frequency} kHz</span></div>${waveformChart(m)}<div class="legend"><span>${signalMode==='raw'?'Raw capture':'Normalised capture'} · ${m.id}</span>${showReference?'<span>Illustrative reference · no decision threshold</span>':''}${signalMode==='overlay'?'<span>Raw overlay shown in grey</span>':''}</div></section><div class="metric-row"><div class="metric"><p>TOF</p><strong>${m.tof??'Unavailable'} ${m.tof?'<small>µs</small>':''}</strong></div><div class="metric"><p>Peak energy</p><strong>${m.peakEnergy?.toLocaleString('en-NZ')??'Unavailable'} ${m.peakEnergy?'<small>a.u.</small>':''}</strong></div><div class="metric"><p>Attenuation feature</p><strong>${m.attenuation?.toFixed(3)??'Unavailable'}</strong><small>Demo scale</small></div><div class="metric"><p>Signal-to-noise ratio</p><strong>${m.snr} <small>dB · demo</small></strong></div></div><details class="model-section" open><summary>Model status & uncertainty</summary><div class="inline-content"><p><strong>No validated engineering model is connected.</strong> Capacity, fibre strength, and ranges are fixed scenario fixtures. They are not calculated from the plotted signal, AR%, or an approved strength equation.</p><p>The range shows how uncertainty could be presented. It is not a 95% prediction interval; coverage and calibration remain unresolved.</p><p>Local fibre strength, remaining fibre strength, whole-pole capacity, and permission to climb are separate concepts. No climb decision is calculated.</p></div></details><details class="model-section"><summary>Processing & reference concepts</summary><div class="inline-content"><p><strong>Raw → normalised → features → engineering model → result.</strong> In this mockup only, the normalised plot multiplies a synthetic trace by the recorded demo correction factor (${m.settings.correction}). This is not the production normalisation routine.</p><dl class="keyvals"><div><dt>Groundline / field / library</dt><dd>Reference types retained</dd></div><div><dt>Threshold profiles</dt><dd>Not established</dd></div><div><dt>AR% / RSM%</dt><dd>Not calculated</dd></div><div><dt>Algorithm</dt><dd>${VERSION} · simulation</dd></div><div><dt>Probe calibration</dt><dd>${esc(m.calibrationId)}</dd></div><div><dt>Reference firmware label</dt><dd>${esc(m.firmware)}</dd></div></dl><p>The current app exposes GL, field, library and additional-test comparisons. Here they are consolidated into one measurement selector and comparison view. The plotted reference is illustrative, not a pass/fail boundary.</p></div></details><details class="model-section"><summary>Why a low signal is not a strength result</summary><div class="inline-content"><p>The correspondence identifies weak or missing peaks, poor contact, noise, ringing, moisture, probe variation, and phase alignment as possible causes. An unusable capture needs a repeat; an inconclusive interpretation needs more evidence.</p><p>The June 2025 technical note and July 2026 AR code commentary conflict. The later commentary describes an attenuation-derived calculation using geometry and acquisition settings. Neither is treated here as a verified current implementation.</p></div></details><div class="form-footer">${btn('Open Expert / Research','enable-research','ghost','flask')}</div>`;
}
