function settingsPage(){return `${heading('Workspace preferences','Settings','Display preferences and demonstration controls.')}<div class="stack"><section class="panel"><div class="panel-body"><label class="toggle-row"><div><h3>Expert / Research mode</h3><p>Show analysis bands, acquisition settings, and calibration diagnostics.</p></div><input type="checkbox" id="research-toggle" ${researchEnabled?'checked':''}></label><div class="toggle-row"><div><h3>Capacity units</h3><p>Same stored kN fixture, converted for display. Geometry stays in mm / m.</p></div><select class="control" id="units" style="width:130px" aria-label="Capacity units"><option value="metric" ${record.settings.units==='metric'?'selected':''}>kN</option><option value="imperial" ${record.settings.units==='imperial'?'selected':''}>lbf</option></select></div><label class="toggle-row"><div><h3>Demo existing restriction</h3><p>Exercise an Axonic-supplied restriction. It takes precedence over the ultrasonic result.</p></div><input type="checkbox" id="restriction-toggle" ${record.asset.restriction?'checked':''}></label></div></section><section class="panel"><div class="panel-head"><h2>Data & integration</h2>${badge('Local only','neutral')}</div><div class="panel-body"><p class="body-copy">This prototype stores fictional pole records in this browser. There is no hardware connection, live Axonic API, cloud sync, authentication, or messaging. Export a record to inspect the proposed shared schema.</p><div class="form-footer">${btn('Export current record','export','ghost','download')}${btn('Restart current scenario','reset','ghost','repeat')}</div><p class="subtle-note">${storageOK?'Local saving is available.':'Local saving is unavailable; records last only for this session.'} Closing or refreshing while a capture is in progress cancels that capture.</p></div></section><details class="model-section"><summary>Evidence and validation boundaries</summary><div class="inline-content"><p>The current screenshots and correspondence establish interface concepts and research needs, not validated climb criteria. No regulatory checklist, classification threshold, frequency-to-strength regression, or physical capacity model has been implemented.</p><p>Detailed source references, conflicts, and open engineering questions are documented in DESIGN_NOTES.md alongside this application.</p></div></details></div>`;}
function selectField(name,label,values,current,help=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(v=>`<option value="${v}" ${String(v)===String(current)?'selected':''}>${v}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;}
function researchPage(){
  if(!researchEnabled)return `${heading('Expert / Research','Research workspace')}<section class="panel empty">${icon('flask')}<h2>Open the research controls</h2><p>Inspect analysis bands, acquisition metadata, and probe effects. All processing and readings are simulated.</p>${btn('Enable Expert / Research','enable-research','primary','flask')}</section>`;
  const s=record.settings;
  return `${heading('Expert / Research','Research workspace','Explore the signal without changing earlier assessment records.',btn('Export record','export','ghost','download'))}<div class="notice">Experimental controls · no validated model. Analysis frequency is distinct from transducer excitation; this prototype does not tune the hardware.</div><section class="panel"><div class="panel-head"><h2>Acquisition & analysis settings</h2>${badge('For future captures','neutral')}</div><div class="panel-body"><form id="research-form"><div class="form-grid">${selectField('frequency','Analysis band (kHz)',FREQUENCIES,s.frequency,'50 kHz legacy concept; other bands are exploratory.')}${selectField('voltage','Tx voltage (V)',[40,70],s.voltage)}${selectField('gain','Gain / amplification',['High','Low'],s.gain)}${selectField('txCount','Transmissions per measurement',[4,8,16],s.txCount)}${selectField('cycles','Cycles per transmission',[1,2,4],s.cycles)}${selectField('group','Probe pair / group',['BA / BB','HA / HB'],s.group,'Changing pair or acquisition preset requires a new demo block check.')}<div class="field"><label for="correction">Multiplicative correction factor</label><input id="correction" name="correction" type="number" min="0.25" max="4" step="0.01" value="${s.correction}" required><small>Illustrative value, not a calibrated physical correction.</small></div></div><div class="form-footer"><button type="submit" class="btn primary">Apply to next capture ${icon('check')}</button>${btn('Restore reference preset','preset','ghost')}</div><p class="error" id="research-error" role="alert"></p></form></div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Frequency sweep</h2>${badge('Analysis of a synthetic signal','yellow')}</div><div class="panel-body"><p class="research-note">Compare the exploratory bands discussed in the correspondence. This is a spectral comparison concept using the latest usable reading, not a sequence of hardware transmissions.</p><fieldset style="border:0;padding:0;margin:0"><legend class="small muted" style="padding-top:18px">Analysis bands</legend><div class="frequencies">${FREQUENCIES.map(f=>`<label class="freq"><input type="checkbox" name="sweep-frequency" value="${f}" checked>${f} kHz</label>`).join('')}</div></fieldset>${btn('Run demo sweep','sweep','primary','wave')}<p class="subtle-note">The 40–50 inch group is labelled 68 kHz in the source table and 48 kHz in its caption. This remains unresolved.</p>${record.research.length?sweepResults(record.research.at(-1)):''}</div></section><details class="model-section"><summary>Research questions retained</summary><div class="inline-content"><p>Which bands are usable across pole sizes? How well do block corrections transfer to wood? Does phase-aligned processing improve the weak-signal cases? Can timing, width, or integrated energy help distinguish noise, moisture, interference, and decay?</p><p>Compare models on independent poles, retain both directions and all rejected attempts, and record firmware, calibration, gain, Tx settings, per-plane geometry, and matched break-test labels. These are research requirements, not claims of model performance.</p></div></details><div class="form-footer"><a class="btn ghost" href="#analyser/signal">${icon('wave')}Raw / normalised signal</a><a class="btn ghost" href="#probes">${icon('probe')}Probe calibration</a></div>`;
}
function sweepResults(run){return `<div class="section-heading"><h3>Sweep result · ${run.measurement}</h3><span class="small muted">${time(run.time)}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Analysis band</th><th>Raw peak energy</th><th>Normalised energy</th><th>SNR</th></tr></thead><tbody>${run.rows.map(x=>`<tr><td>${x.frequency} kHz</td><td>${x.rawEnergy.toLocaleString('en-NZ')} a.u.</td><td>${x.normalisedEnergy.toLocaleString('en-NZ')} a.u.</td><td>${x.snr} dB</td></tr>`).join('')}</tbody></table></div><p class="subtle-note">Synthetic values · no frequency recommendation or strength inference</p>`;}
function preserveDraft(){
  const form=document.querySelector('#pole-scan-form');if(form){if(!draft)draft={canonicalSize:outcome(record)==='additional'?925:pendingPosition.circumference};draft={...draft,...Object.fromEntries(new FormData(form))};}
}
function poleInput(){
  const additional=outcome(record)==='additional'&&!scanSession?.options.repeatOf;
  const raw=draft||{poleId:record.asset.id,length:record.asset.length,poleHeight:record.asset.height,species:record.asset.species,scanHeight:additional?300:pendingPosition.height,size:additional?925:pendingPosition.circumference};
  return {...raw,direction:String(additional?90:pendingPosition.direction),size:raw.canonicalSize??raw.size,sizeMode:raw.canonicalSize!=null||!draft?'circumference':sizeMode};
}
function commitPoleForm(){
  preserveDraft();const form=document.querySelector('#pole-scan-form');if(!form)return false;
  const error=document.querySelector('#pole-form-error'),wasPending=!!record.measurements.at(-1)?.metadataPending;
  try{
    pendingPosition=(busy?updatePoleDetails:completeScanDetails)(record,poleInput());save();error.textContent='';
    document.querySelector('#pole-save-status').textContent=storageOK?'Saved on this device':'Session only';
    if(!busy&&wasPending){render();return true;}
    return true;
  }catch(e){error.textContent=e.message;return false;}
}
function commitMeasurementForm(form,toggle=false){
  if(busy)return false;
  const error=form.querySelector('.measurement-edit-error'),height=form.querySelector('[name="scanHeight"]'),size=form.querySelector('[name="size"]');
  try{
    const oldMode=form.dataset.sizeMode,mode=toggle?(oldMode==='diameter'?'circumference':'diameter'):oldMode;
    const canonical=form.dataset.circumference!==undefined?Number(form.dataset.circumference):oldMode==='diameter'?Number(size.value)*Math.PI:Number(size.value);
    const display=toggle?Math.round(mode==='diameter'?canonical/Math.PI:canonical):size.value;
    const m=updateMeasurementGeometry(record,form.dataset.editId,{scanHeight:height.value,size:display,sizeMode:mode,canonicalCircumference:canonical});
    form.dataset.sizeMode=mode;form.dataset.circumference=String(m.circumference);
    size.value=String(m.enteredSize??Math.round(mode==='diameter'?m.circumference/Math.PI:m.circumference));
    const unit=mode==='diameter'?'Diameter':'Circumference',button=form.querySelector('.size-label-toggle');
    button.innerHTML=unit+' <span>⇄</span>';button.setAttribute('aria-label',unit+'; switch measurement size unit');size.setAttribute('aria-label',unit+' for measurement '+m.id);error.textContent='';
    const card=form.closest('.measurement-card'),template=document.createElement('template');template.innerHTML=measurementCards(record,loadValue,busy);
    const refreshed=template.content.querySelector('#scan-'+CSS.escape(m.id));
    card.querySelector('summary strong').textContent=refreshed.querySelector('summary strong').textContent;
    const loss=card.querySelector('.measurement-loss'),nextLoss=refreshed.querySelector('.measurement-loss');if(loss&&nextLoss)loss.replaceWith(nextLoss);
    const poleSummary=document.querySelector('#pole-summary');if(poleSummary)poleSummary.innerHTML=poleSummaryView(record,loadValue);
    card.querySelector('.engineering-summary,.measurement-message').replaceWith(refreshed.querySelector('.engineering-summary,.measurement-message'));
    const list=card.parentElement,ordered=[...record.measurements].sort((a,b)=>a.height-b.height),current=[...list.querySelectorAll('.measurement-card')];
    if(ordered.some((m,i)=>current[i]?.id!=='scan-'+m.id)){
      const focused=document.activeElement;
      ordered.forEach(m=>list.append(document.getElementById('scan-'+m.id)));
      if(focused&&focused!==document.body)focused.focus({preventScroll:true});
    }
    save();return true;
  }catch(e){error.textContent=e.message;return false;}
}
function toggleSize(){
  preserveDraft();const raw=poleInput();const c=raw.sizeMode==='diameter'?Number(raw.size)*Math.PI:Number(raw.size);
  if(!Number.isFinite(c)||c<=0){document.querySelector('#pole-form-error').textContent='Enter a size before switching.';return;}
  sizeMode=sizeMode==='diameter'?'circumference':'diameter';
  draft={...draft,canonicalSize:c,size:String(Math.round(sizeMode==='diameter'?c/Math.PI:c))};
  const input=document.querySelector('#pole-size'),button=document.querySelector('[data-action="toggle-size"]'),label=sizeMode==='diameter'?'Diameter':'Circumference';
  input.value=draft.size;input.setAttribute('aria-label',label);button.innerHTML=label+' <span>⇄</span>';button.setAttribute('aria-label',label+'; switch to '+(sizeMode==='diameter'?'circumference':'diameter'));
}

function openDialog(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
async function capture(options={}){
  if(busy)return;preserveDraft();const captureRecord=record;
  if(options.entrySizeMode)sizeMode=options.entrySizeMode;
  if(options.height!==undefined||options.circumference!==undefined){
    const c=options.circumference??pendingPosition.circumference;
    draft={poleId:record.asset.id,length:record.asset.length,poleHeight:record.asset.height,species:record.asset.species,...draft,scanHeight:options.height??pendingPosition.height,size:Math.round(sizeMode==='diameter'?c/Math.PI:c),canonicalSize:c};
    pendingPosition={...pendingPosition,direction:options.direction??pendingPosition.direction};
  }
  try{scanSession=beginAcquisition(record,{...options,cycle:true,entrySizeMode:sizeMode});}catch(e){toast(e.message);return;}
  busy=true;publishScan(true,Number(poleInput().scanHeight));dialog.close();render();const session=scanSession,start=Date.now();
  const tick=()=>{const elapsed=Date.now()-start;
    const count=document.querySelector('#scan-countdown');
    if(count)count.textContent='Scanning · '+Math.max(0,Math.ceil((SCAN_DURATION_MS-elapsed)/1000))+' s';
  };tick();const timer=setInterval(tick,250);session.timer=timer;
  try{
    await new Promise(resolve=>{session.resolve=resolve;session.timeout=setTimeout(resolve,SCAN_DURATION_MS);});
    if(session.cancelled||captureRecord!==record)return;
    preserveDraft();
    session.options.entrySizeMode=sizeMode;
    const m=finishAcquisition(captureRecord,session,poleInput());selectedMeasurement=m.id;
    pendingPosition={height:m.height,direction:m.direction,circumference:m.circumference};
    if(outcome(captureRecord)==='additional')draft={...draft,scanHeight:'300',size:String(Math.round(sizeMode==='diameter'?925/Math.PI:925)),canonicalSize:925};
    operatorAdd=false;save();
  }catch(e){toast(e.message);}finally{clearInterval(timer);if(scanSession===session){busy=false;scanSession=null;render();document.getElementById('scan-'+captureRecord.measurements.at(-1)?.id)?.scrollIntoView({block:'start'});}}
}
function addDialog(){openDialog('Add a measurement',`<p>Use the same acquisition service as Safe2Climb. Positions and circumference belong to each measurement plane.</p><form id="measurement-form"><div class="form-grid"><div class="field"><label for="height">Height above GL (mm)</label><input id="height" name="height" type="number" value="0" min="-1000" max="3000" required><small>Negative means below groundline.</small></div><div class="field"><label for="direction">Direction</label><select id="direction" name="direction"><option value="0">A · 0°</option><option value="90">B · 90°</option></select></div><div class="field"><label for="circumference">Circumference at this plane (mm)</label><input id="circumference" name="circumference" type="number" value="${record.asset.circumference}" min="300" max="1800" required></div></div><div class="form-footer"><button class="btn primary" type="submit">${icon('wave')}Take reading</button></div></form>`);}
function exportDialog(){openDialog('Export demo record',`<p>Preview the shared record. All values are fictional and engineering outputs are explicitly unvalidated.</p><label for="export-preview">Assessment JSON</label><textarea id="export-preview" class="export-preview" readonly spellcheck="false">${esc(JSON.stringify(exportRecord(record),null,2))}</textarea><div class="form-footer">${btn('Download JSON','download-record','primary','download')}</div><p class="subtle-note">If this embedded browser does not support downloads, select and copy the JSON above or open the mockup in Edge/Chrome.</p>`);}
function download(){const blob=new Blob([JSON.stringify(exportRecord(record),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`DEMO-${record.asset.id}-assessment.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('JSON download requested');}
function changeScenario(key){if(!SCENARIOS[key])throw new Error('Unknown demo scenario');if(busy)throw new Error('Wait for the current capture to finish.');const previous=route();scenario=key;draft=null;record=records[scenario]||newRecord(scenario);selectedMeasurement='';pendingPosition=positionFromRecord();save();go(key==='detailed'?'analyser/summary':previous.startsWith('analyser')?'analyser/summary':previous==='asset'?'asset':'field');}
function runSweep(frequencies){const rows=frequencySeries(record,frequencies);const run={id:`SWEEP-${record.research.length+1}`,time:new Date().toISOString(),measurement:rows[0].measurement,rows};record.research.push(run);record.history.unshift({time:run.time,type:'Research sweep saved',text:`${run.id} · ${frequencies.join(' / ')} kHz · synthetic analysis, no hardware transmissions`});save();render();return run;}
function blockCheck(){
  if(!record.connected){toast('Connect the demo probe pair before a block check');return;}
  openDialog('Demo block check',`<p>Place both probes in the common calibration block. This demonstration loads a fixture response; it does not communicate with a device.</p><dl class="keyvals"><div><dt>Block</dt><dd>BLOCK-DEMO-01</dd></div><div><dt>Pair</dt><dd>${record.settings.group}</dd></div><div><dt>Preset</dt><dd>${record.settings.voltage} V / ${record.settings.gain}</dd></div></dl><div class="form-footer">${btn('Capture demo block response','confirm-calibration','primary','probe')}</div>`);
}
function positionDialog(){openDialog('Measurement position',`<p>Only change these when you move to another plane or direction. A below-ground measurement uses a negative height.</p><form id="position-form"><div class="form-grid"><div class="field"><label for="position-height">Height above GL (mm)</label><input id="position-height" name="height" type="number" value="${pendingPosition.height}" min="-1000" max="3000" required></div><div class="field"><label for="position-direction">Direction</label><select id="position-direction" name="direction"><option value="0" ${pendingPosition.direction===0?'selected':''}>A · 0°</option><option value="90" ${pendingPosition.direction===90?'selected':''}>B · 90°</option></select></div><div class="field full"><label for="position-circumference">Circumference at this plane (mm)</label><input id="position-circumference" name="circumference" type="number" value="${pendingPosition.circumference}" min="300" max="1800" required><small>GL value starts from Axonic. Verify the value at a new plane.</small></div></div><div class="form-footer"><button class="btn primary" type="submit">Use this position</button></div></form>`);}
function poleContext(){openDialog('Pole details from Axonic',`<dl class="keyvals"><div><dt>Asset</dt><dd>${esc(record.asset.id)}</dd></div><div><dt>Species</dt><dd>${esc(record.asset.species)}</dd></div><div><dt>Length</dt><dd>${record.asset.length} m</dd></div><div><dt>Height above GL</dt><dd>${record.asset.height} m</dd></div><div><dt>GL circumference</dt><dd>${record.asset.circumference} mm</dd></div><div><dt>Class</dt><dd>${esc(record.asset.class)}</dd></div></dl><p class="subtle-note">Demo data. These values are reused; there is no second pole-information form.</p><div class="form-footer"><button class="btn ghost" data-route="asset">View Axonic asset</button></div>`);}
function concernDialog(){openDialog('Record a pre-climb concern',`<p>Record only the exception. A concern routes this demo to review and is retained with the pole.</p><form id="concern-form"><div class="form-grid"><div class="field full"><label for="concern-type">Concern</label><select id="concern-type" name="type">${['Visible decay or damage','Lean or groundline concern','Marking / restriction','Unable to complete inspection','Other concern'].map(x=>`<option ${record.concern?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label for="concern-note">Note (optional)</label><textarea id="concern-note" name="note" maxlength="500">${esc(record.concern?.note||'')}</textarea></div></div><div class="form-footer"><button class="btn primary" type="submit">Record concern</button>${record.concern?btn('Clear demo concern','clear-concern','ghost'):''}</div></form>`);}
function confirmCalibration(){
  if(!record.connected){toast('Connect the demo probes first');return;}
  const s=record.settings;const correction=s.group==='BA / BB'?1.08:0.92;
  const entry={id:`CAL-DEMO-${String(record.calibrationEvents.length+2).padStart(2,'0')}`,time:new Date().toISOString(),group:s.group,voltage:s.voltage,gain:s.gain,correction,block:'BLOCK-DEMO-01',validated:false};
  record.calibrationEvents.push(entry);record.calibration='current-demo';record.settings.correction=correction;
  record.history.unshift({time:entry.time,type:'Demo block check recorded',text:`${entry.id} · ${s.group} · correction ${correction} · not a physical calibration`});save();dialog.close();render();toast('Demo calibration profile loaded');
}
document.addEventListener('click',e=>{
  if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();return;}
  const signal=e.target.closest('[data-signal-mode]');if(signal){signalMode=signal.dataset.signalMode;render();return;}
  const r=e.target.closest('[data-route]');if(r){dialog.close();go(r.dataset.route);return;}
  const m=e.target.closest('[data-measurement]');if(m){selectedMeasurement=m.dataset.measurement;go('analyser/signal');return;}
  const el=e.target.closest('[data-action]');if(!el)return;
  const action=el.dataset.action;if(busy&&!['close','toggle-size','photo','new-pole','mobile-menu'].includes(action))return;
  if(action==='host-workflow'){openDialog(el.dataset.workflow,'<p>This existing Axonic workflow is shown for context. Its capture form is outside this UB1000 mockup.</p>');return;}
  if(action==='mobile-menu'&&(route()==='asset'||route().startsWith('axonic/'))){openDialog('Axonic','<div class="stack"><button type="button" class="btn primary" data-action="new-pole">'+icon('plus')+'Capture new pole</button><button class="btn ghost" data-route="analyser/summary">UB1000 measurement</button></div>');return;}
  if(action==='toggle-size'){toggleSize();return;}
  if(action==='toggle-measurement-size'){commitMeasurementForm(el.closest('.measurement-edit'),true);return;}
  if(action==='new-pole'){startNewPole();return;}
  if(action==='repeat-measurement'){const form=el.closest('.measurement-card').querySelector('.measurement-edit');if(form&&!commitMeasurementForm(form))return;const original=record.measurements.find(m=>m.id===el.dataset.repeatId);if(original)capture({height:original.height,direction:original.direction,circumference:original.circumference,entrySizeMode:original.sizeMode||'circumference',repeatOf:original.id});return;}
  if(action==='start-survey'){capture();return;}
  if(action==='phone-preview'){dialog.close();openPhonePreview();}
  else if(action==='capture')capture();
  else if(action==='operator-capture')capture({...pendingPosition});
  else if(action==='position')positionDialog();
  else if(action==='pole-context')poleContext();
  else if(action==='preclimb-context')openDialog('Existing pre-climb context',`<p>Carried over from the Axonic demo asset. The operator is not asked to re-enter these checks.</p><dl class="keyvals"><div><dt>Work</dt><dd>${esc(record.asset.workType)}</dd></div><div><dt>Visual / sounding checks</dt><dd>Completed · demo assumption</dd></div><div><dt>Recorded lean</dt><dd>${record.asset.lean}°</dd></div><div><dt>Existing restriction</dt><dd>${record.asset.restriction?'Present':'None in demo fixture'}</dd></div></dl><p class="subtle-note">These records must be verified by the host Axonic workflow in a real implementation. This prototype does not replace the required inspection.</p><div class="form-footer">${btn('Report a new concern','concern','ghost','alert')}</div>`);
  else if(action==='concern')concernDialog();
  else if(action==='clear-concern'){record.concern=null;record.history.unshift({time:new Date().toISOString(),type:'Demo concern cleared',text:'Cleared by the demo operator; earlier concern retained in history.'});save();dialog.close();render();}
  else if(action==='add')addDialog();
  else if(action==='close')dialog.close();
  else if(action==='reset'){dialog.close();draft=null;const priorAsset={...record.asset},priorPhotos=record.photos;record=newRecord('normal');record.asset=priorAsset;record.photos=priorPhotos;record.scenario='normal';selectedMeasurement='';pendingPosition=positionFromRecord();save();render();toast('Demo scans restarted');}
  else if(action==='connect'){record.connected=!record.connected;save();render();toast(record.connected?'Demo probes connected':'Demo probes disconnected');}
  else if(action==='request-review'){if(!record.reviewRequested){record.reviewRequested=true;record.history.unshift({time:new Date().toISOString(),type:'Engineering review requested',text:'Recorded locally. No message or external notification was sent.'});save();render();}toast('Review request saved on this device · not sent');}
  else if(action==='export')exportDialog();
  else if(action==='download-record')download();
  else if(action==='enable-research'){researchEnabled=true;save();go('research');}
  else if(action==='calibrate')blockCheck();
  else if(action==='confirm-calibration')confirmCalibration();
  else if(action==='invalidate-calibration'){record.calibration='check-required';save();render();toast('Demo profile now requires a block check');}
  else if(action==='preset'){const units=record.settings.units;record.settings={...DEFAULT_SETTINGS,units};record.calibration='check-required';save();render();toast('Reference preset restored · run a demo block check');}
  else if(action==='sweep'){try{const frequencies=Array.from(document.querySelectorAll('[name="sweep-frequency"]:checked'),x=>Number(x.value));runSweep(frequencies);toast('Synthetic frequency comparison saved');}catch(error){toast(error.message);}}
  else if(action==='mobile-menu')openDialog('Tools & detail',`<div class="stack">${btn('Restart demo scans','reset','ghost','repeat')}${[['analyser/summary','Pole Analyser','wave'],['analyser/detail','Assessment detail','chart'],['analyser/history','History','clock'],['probes','Probe management','probe'],['settings','Settings','settings'],...(researchEnabled?[['research','Expert / Research','flask']]:[])].map(([to,label,ic])=>`<button class="btn ghost" data-route="${to}">${icon(ic)}${label}</button>`).join('')}</div>`);
});
document.addEventListener('input',e=>{const measurementForm=e.target.closest('.measurement-edit');if(measurementForm&&e.target.name==='size')delete measurementForm.dataset.circumference;if(e.target.closest('#pole-scan-form')){preserveDraft();if(e.target.name==='size')delete draft.canonicalSize;}});
document.addEventListener('change',e=>{
  const measurementForm=e.target.closest('.measurement-edit');if(measurementForm){commitMeasurementForm(measurementForm);return;}
  if(e.target.closest('#pole-scan-form')){commitPoleForm();return;}
  if(e.target.id==='scenario'){if(busy)return;changeScenario(e.target.value);}
  if(e.target.id==='research-toggle'){researchEnabled=e.target.checked;save();render();}
  if(e.target.id==='signal-reading'){selectedMeasurement=e.target.value;render();}
  if(e.target.id==='show-reference'){showReference=e.target.checked;render();}
  if(e.target.id==='units'){record.settings.units=e.target.value;save();render();}
  if(e.target.id==='restriction-toggle'){record.asset.restriction=e.target.checked?'Existing demo restriction: refer to the asset owner before proceeding.':null;record.history.unshift({time:new Date().toISOString(),type:'Demo asset restriction changed',text:record.asset.restriction||'Demo restriction removed by the scenario operator.'});save();render();}
});
document.addEventListener('submit',e=>{
  if(e.target.matches('.measurement-edit')){e.preventDefault();commitMeasurementForm(e.target);return;}
  if(e.target.id==='pole-scan-form'){e.preventDefault();if(busy)return;commitPoleForm();return;}
  if(e.target.id==='position-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));pendingPosition={height:Number(data.height),direction:Number(data.direction),circumference:Number(data.circumference)};dialog.close();render();}
  if(e.target.id==='concern-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));record.concern={type:data.type,note:data.note.trim(),time:new Date().toISOString()};record.history.unshift({time:record.concern.time,type:'Pre-climb concern recorded',text:`${record.concern.type}${record.concern.note?' · '+record.concern.note:''}`});save();dialog.close();render();toast('Concern saved with this pole · review required');}
  if(e.target.id==='measurement-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));capture({height:Number(data.height),direction:Number(data.direction),circumference:Number(data.circumference)});}
  if(e.target.id==='research-form'){
    e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const settings={...record.settings,...data};
    for(const key of ['frequency','voltage','txCount','cycles','correction'])settings[key]=Number(settings[key]);
    try{validateSettings(settings);if(['group','voltage','gain','txCount','cycles'].some(key=>settings[key]!==record.settings[key]))record.calibration='check-required';record.settings=settings;record.history.unshift({time:new Date().toISOString(),type:'Research settings changed',text:`Future captures only · ${settings.frequency} kHz analysis · ${settings.voltage} V / ${settings.gain} · ${settings.group}`});save();render();toast('Settings saved for future captures');}catch(error){document.querySelector('#research-error').textContent=error.message;}
  }
});
window.addEventListener('hashchange',()=>{preserveDraft();render();window.scrollTo(0,0);});
installPhotos({getRecord:()=>record,isBusy:()=>busy,save,render,openDialog,dialog,esc,toast,preserveDraft});
save();render();

if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  const tool={name:'select_demo_scenario',title:'Select UB1000 demo scenario',description:'Navigate to a named simulated pole assessment; no hardware or Axonic access.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(SCENARIOS)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='scenario')||typeof input.scenario!=='string')throw new Error('A supported scenario is required');changeScenario(input.scenario);return {scenario,asset:record.asset.id,state:outcome(record),demo:true};}};
  try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

connectLab();
